{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "MSSQL security alerts have no designated email recipients",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The policy is enabled but does not configure email_addresses, so security alerts are not sent to a designated response team."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "MSSQL security alerts are not sent to account administrators",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The email_account_admins setting is absent, so account administrators and co-administrators are not explicitly configured to receive detected threat alerts."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "MSSQL threat detection does not cover all alert types",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The policy disables SQL injection and data exfiltration alerts, leaving high-impact database attack activity undetected by this alert policy."
    }
  ],
  "patched_code": "variable \"security_alert_email_addresses\" {\n  description = \"Email addresses that receive MSSQL security alerts.\"\n  type        = list(string)\n  nullable    = false\n\n  validation {\n    condition     = length(var.security_alert_email_addresses) > 0\n    error_message = \"At least one MSSQL security alert email address must be provided.\"\n  }\n}\n\nresource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts            = []\n  email_account_admins       = true\n  email_addresses            = var.security_alert_email_addresses\n  retention_days             = 20\n}\n",
  "fix_summary": "Enabled all MSSQL threat detection alert types, configured alerts for account administrators, and added a required non-empty list of designated alert recipients without introducing placeholder email addresses."
}
